$reviewedPercent = $report['total'] > 0 ? round($summary['reviewed'] / $report['total'] * 100, 1) : 0;
$enrolledCount = (int) ($summary['statuses']['enrolled'] ?? 0);
$enrolledPercent = $report['total'] > 0 ? round($enrolledCount / $report['total'] * 100, 1) : 0;
$drilldownLabels = [
    'stage:submitted' => 'Submitted', 'stage:screening' => 'Screening', 'stage:interview' => 'Interview', 'stage:accepted' => 'Accepted', 'stage:enrolled' => 'Enrolled',
    'attention:unassigned' => 'Unassigned Applications', 'attention:interviews_week' => 'Interviews Scheduled This Week', 'attention:idle' => 'Applications Idle More Than 7 Days', 'attention:incomplete_documents' => 'Incomplete Documents',
    'status:declined' => 'Declined', 'status:documents_incomplete' => 'Documents Incomplete',
];
$drilldown = $filter('drilldown');
$drilldownUrl = static function (string $value) use ($report, $drilldown): string {
    $query = $report['filters'];
    unset($query['page']);
    if ($drilldown === $value) unset($query['drilldown']);
    else $query['drilldown'] = $value;
    return '/staff/reports?' . http_build_query(array_filter($query, static fn ($item): bool => is_scalar($item) && (string) $item !== '')) . '#report-results';
};
$sortUrl = static function (string $key) use ($report): string {
    $query = $report['filters'];
    unset($query['page']);
    $direction = $report['filters']['report_sort'] === $key && $report['filters']['report_direction'] === 'asc' ? 'desc' : 'asc';
    $query['report_sort'] = $key;
    $query['report_direction'] = $direction;
    return '/staff/reports?' . http_build_query(array_filter($query, static fn ($item): bool => is_scalar($item) && (string) $item !== '')) . '#report-results';
};
$filterValues = array_filter($report['filters'], static fn ($item): bool => is_scalar($item) && (string) $item !== '');
