$yearNames = array_column($years, 'label', 'id');
$reviewerNames = array_column($reviewers, 'full_name', 'id');
$activeFilterChips = [];
foreach (['q' => 'Search', 'status' => 'Status'] as $filterKey => $label) if ($filter($filterKey) !== '') $activeFilterChips[] = ['key' => $filterKey, 'label' => $label . ': ' . ($filterKey === 'status' ? ($statusLabels[$filter($filterKey)] ?? $filter($filterKey)) : $filter($filterKey))];
if ($filter('program_id') !== '') $activeFilterChips[] = ['key' => 'program_id', 'label' => 'Program: ' . ($programNames[$filter('program_id')] ?? 'Selected program')];
if ($filter('year_id') !== '') $activeFilterChips[] = ['key' => 'year_id', 'label' => 'Academic year: ' . ($yearNames[$filter('year_id')] ?? 'Selected year')];
if ($filter('reviewer_id') !== '') $activeFilterChips[] = ['key' => 'reviewer_id', 'label' => 'Reviewer: ' . ($reviewerNames[$filter('reviewer_id')] ?? 'Selected reviewer')];
if ($filter('documents') !== '') $activeFilterChips[] = ['key' => 'documents', 'label' => 'Document completion: ' . ($filter('documents') === 'complete' ? 'All verified' : 'Incomplete')];
if ($reportDatePreset !== '') $activeFilterChips[] = ['key' => 'date_range', 'clear_keys' => ['date_range', 'start_date', 'end_date'], 'label' => 'Date range: ' . $dateRangeLabel . ($reportDatePreset === 'custom' && $filter('start_date') !== '' ? ' · ' . $filter('start_date') . ' to ' . $filter('end_date') : '')];
if ($drilldown !== '' && isset($drilldownLabels[$drilldown])) $activeFilterChips[] = ['key' => 'drilldown', 'label' => 'Filtered by: ' . $drilldownLabels[$drilldown]];
$filterResetUrl = '/staff/reports?per_page=' . (int) ($report['pagination']['page_size'] ?? 20) . '#report-results';
?>
